            devdoc: {
              kind: "dev",
              methods: {
                "batchWithdrawMaxTokens(address[])": {
                  details: "This function allows a user to claim all of their tokens from the margin account.",
                  params: {
                    _tokens: "Array of tokens to claim."
                  }
                },
                "cancelOwnershipHandover()": {
                  details: "Cancels the two-step ownership handover to the caller, if any."
                },
                "completeOwnershipHandover(address)": {
                  details: "Allows the owner to complete the two-step ownership handover to `pendingOwner`. Reverts if there is no existing ownership handover requested by `pendingOwner`."
                },
                "creditFee(address,uint256,address,uint256)": {
                  details: "This function allows a verified market to register fee collected",
                  params: {
                    _assetA: "Address of first asset",
                    _assetB: "Address of second asset",
                    _feeA: "Fee amount of _assetA to be credited",
                    _feeB: "Fee amount of _assetB to be credited"
                  }
                },
                "creditUser(address,address,uint256,bool)": {
                  details: "This function is only callable by a verified market. Verified markets credit user balances.",
                  params: {
                    _amount: "amount to credit.",
                    _token: "address of token to be credit.",
                    _useMargin: "whether to use margin or not - if not, user will receive token through an erc20 transfer",
                    _user: "address of the user whose account should be credited."
                  }
                },
                "creditUsersEncoded(bytes)": {
                  details: "This function is only callable by a verified market. Verified markets credit a bunch of users the tokens.",
                  params: {
                    _encodedData: "Address of the user whose account should be credited."
                  }
                },
                "debitUser(address,address,uint256)": {
                  details: "This function is only callable by a verified market. Verified markets consume user balances.",
                  params: {
                    _amount: "amount to debit.",
                    _token: "address of token to be debited.",
                    _user: "address of the user whose account should be debited."
                  }
                },
                "deposit(address,address,uint256)": {
                  details: "Function for EOAs to deposit tokens on behalf of a user.",
                  params: {
                    _amount: "amount to credit.",
                    _token: "address of token to be credit.",
                    _user: "Address of the user whose account should be credited."
                  }
                },
                "getBalance(address,address)": {
                  details: "Function to check balance of a user for a given token.",
                  params: {
                    _token: "tokenA addresss",
                    _user: "user addresss"
                  }
                },
                "owner()": {
                  details: "Returns the owner of the contract."
                },
                "ownershipHandoverExpiresAt(address)": {
                  details: "Returns the expiry timestamp for the two-step ownership handover to `pendingOwner`."
                },
                "proxiableUUID()": {
                  details: "Returns the storage slot used by the implementation, as specified in [ERC1822](https://eips.ethereum.org/EIPS/eip-1822). Note: The `notDelegated` modifier prevents accidental upgrades to an implementation that is a proxy contract."
                },
                "renounceOwnership()": {
                  details: "Allows the owner to renounce their ownership."
                },
                "requestOwnershipHandover()": {
                  details: "Request a two-step ownership handover to the caller. The request will automatically expire in 48 hours (172800 seconds) by default."
                },
                "transferOwnership(address)": {
                  details: "Allows the owner to transfer the ownership to `newOwner`."
                },
                "updateMarkets(address)": {
                  details: "This function allows the router to register an official verified market.",
                  params: {
                    _marketAddress: "Address of the orderbook of the market."
                  }
                },
                "upgradeToAndCall(address,bytes)": {
                  details: "Upgrades the proxy's implementation to `newImplementation`. Emits a {Upgraded} event. Note: Passing in empty `data` skips the delegatecall to `newImplementation`."
                },
                "withdraw(uint256,address)": {
                  details: "Function for users to withdraw their assets.",
                  params: {
                    _amount: "amount to withdraw.",
                    _token: "address of token to be withdrawn."
                  }
                }
              },
              version: 1
            },
