            devdoc: {
              kind: "dev",
              methods: {
                "DOMAIN_SEPARATOR()": {
                  details: "Returns the EIP-712 domain separator for the EIP-2612 permit."
                },
                "allowance(address,address)": {
                  details: "Returns the amount of tokens that `spender` can spend on behalf of `owner`."
                },
                "approve(address,uint256)": {
                  details: "Sets `amount` as the allowance of `spender` over the caller's tokens. Emits a {Approval} event."
                },
                "balanceOf(address)": {
                  details: "Returns the amount of tokens owned by `owner`."
                },
                "decimals()": {
                  details: "Returns the decimals places of the token."
                },
                "deposit(uint256,uint256,uint256,address)": {
                  details: "Deposits token1 and token2 into the vault and mints shares to the receiver."
                },
                "mint(uint256,address)": {
                  details: "Mints shares to the receiver in exchange for depositing token1 and token2."
                },
                "name()": {
                  details: "Returns the name of the token."
                },
                "nonces(address)": {
                  details: "Returns the current nonce for `owner`. This value is used to compute the signature for EIP-2612 permit."
                },
                "permit(address,address,uint256,uint256,uint8,bytes32,bytes32)": {
                  details: "Sets `value` as the allowance of `spender` over the tokens of `owner`, authorized by a signed approval by `owner`. Emits a {Approval} event."
                },
                "previewDeposit(uint256,uint256)": {
                  details: "Previews the amount of shares to be minted for a given deposit of token1 and token2."
                },
                "previewMint(uint256)": {
                  details: "Previews the amount of token1 and token2 to be received for a given amount of shares to be minted."
                },
                "previewWithdraw(uint256)": {
                  details: "Previews the amount of token1 and token2 to be received for a given amount of shares to be burned."
                },
                "proxiableUUID()": {
                  details: "Returns the storage slot used by the implementation, as specified in [ERC1822](https://eips.ethereum.org/EIPS/eip-1822). Note: The `notDelegated` modifier prevents accidental upgrades to an implementation that is a proxy contract."
                },
                "setMarketParams()": {
                  details: "Fetches and stores the market params from the market contract."
                },
                "symbol()": {
                  details: "Returns the symbol of the token."
                },
                "totalAssets()": {
                  details: "Returns the total assets of the vault in token1 and token2."
                },
                "totalSupply()": {
                  details: "Returns the amount of tokens in existence."
                },
                "transfer(address,uint256)": {
                  details: "Transfer `amount` tokens from the caller to `to`. Requirements: - `from` must at least have `amount`. Emits a {Transfer} event."
                },
                "transferFrom(address,address,uint256)": {
                  details: "Transfers `amount` tokens from `from` to `to`. Note: Does not update the allowance if it is the maximum uint256 value. Requirements: - `from` must at least have `amount`. - The caller must have at least `amount` of allowance to transfer the tokens of `from`. Emits a {Transfer} event."
                },
                "upgradeToAndCall(address,bytes)": {
                  details: "Upgrades the proxy's implementation to `newImplementation`. Emits a {Upgraded} event. Note: Passing in empty `data` skips the delegatecall to `newImplementation`."
                },
                "withdraw(uint256,address,address)": {
                  details: "Withdraws token1 and token2 from the vault by burning the specified amount of shares."
                }
              },
              version: 1
            },
            userdoc: {
              kind: "user",
              methods: {},
              version: 1
            }
